#!/usr/bin/env python3
"""Emit a VMBS-manufactured Virtual Circuit Board as VB.NET source."""
import argparse,json,re,hashlib
from pathlib import Path
ap=argparse.ArgumentParser(); ap.add_argument('code'); ap.add_argument('out'); ap.add_argument('--class-name',default='GeneratedVCB'); ap.add_argument('--board-id'); ap.add_argument('--display-name'); a=ap.parse_args(); c=json.load(open(a.code,encoding='utf-8'))
def vbstr(x): return '"'+str(x).replace('"','""')+'"'
def j(x): return vbstr(json.dumps(x,sort_keys=True,separators=(',',':')))
def ident(x): return re.sub(r'[^A-Za-z0-9_]','_',x)
ins=c['instructions']; modules=[x for x in ins if x.get('op')=='ALLOC_MODULE']; platform=next(x for x in ins if x.get('op')=='ATTACH_PLATFORM'); controls=[x for x in ins if x.get('op')=='CREATE_CONTROL']; props=[x for x in ins if x.get('op')=='DEFINE_PROPERTY' and x.get('property') in ('IO_BASE','IRQ','BOOT_ROM')]; fin=next(x for x in ins if x.get('op')=='FINALIZE_BOARD'); primary=next((m for m in modules if m['module_id'].startswith('VMB.NET.')),modules[0])
board_id=a.board_id or ident(Path(a.out).name.replace('.vcb.vb','')).upper(); display=a.display_name or board_id.replace('_',' '); category='NETWORK' if primary['module_id'].startswith('VMB.NET.') else 'EXPANSION'; bus=platform['platform']; connector_bits=8 if bus.upper()=='ISA8' else 16
install={'card_id':board_id,'display_name':display,'category':category,'bus':bus,'connector_bits':connector_bits,'board_code_format':c['format'],'primary_module_id':primary['module_id'],'required_modules':[m['module_id'] for m in modules],'controls':[{'id':x['id'],'kind':x['kind'],'elements':x['elements'],'change_while_powered':x['change_while_powered']} for x in controls],'properties':[{'name':p['property'],'allowed':p['allowed_values'],'default':p.get('default_value'),'selectors':p.get('selectors',[])} for p in props],'persistent_devices':[x for x in ins if x.get('op')=='CREATE_DEVICE_SLOT'],'completion':{'hardware_tits':fin['hardware_tits'],'execution_tits':fin['execution_tits'],'default_execution_tits':fin.get('default_execution_tits',fin['execution_tits'])}}
L=[]; w=L.append
w("' AUTO-GENERATED BY VMBS. Do not hand-edit; edit BS and regenerate this VCB."); w('Option Strict On'); w('Option Explicit On'); w('Imports WindowsApplication1'); w('')
cls=ident(a.class_name); w(f'Public NotInheritable Class {cls}'); w('    Implements IVirtualCircuitBoard'); w(f'    Public ReadOnly Property BoardId As String Implements IVirtualCircuitBoard.BoardId = {vbstr(board_id)}'); w(f'    Public ReadOnly Property DisplayName As String Implements IVirtualCircuitBoard.DisplayName = {vbstr(display)}'); w(f'    Public ReadOnly Property Category As String Implements IVirtualCircuitBoard.Category = {vbstr(category)}'); w(f'    Public ReadOnly Property Bus As String Implements IVirtualCircuitBoard.Bus = {vbstr(bus)}'); w(f'    Public ReadOnly Property ConnectorBits As Integer Implements IVirtualCircuitBoard.ConnectorBits = {connector_bits}'); w(f'    Public ReadOnly Property InstallHeaderJson As String Implements IVirtualCircuitBoard.InstallHeaderJson = {j(install)}'); w(''); w('    Public Sub Build(runtime As IVmbBoardRuntime) Implements IVirtualCircuitBoard.Build')
for x in ins:
 op=x['op']
 if op=='ALLOC_MODULE': w(f"        runtime.AllocateModule({vbstr(x['id'])}, {vbstr(x['module_id'])}, {vbstr(x['part_id'])})")
 elif op=='ATTACH_PLATFORM': w(f"        runtime.AttachPlatform({vbstr(x['id'])}, {vbstr(x['platform'])}, {j(x['signals'])})")
 elif op=='CREATE_CONTROL': w(f"        runtime.CreateControl({vbstr(x['id'])}, {vbstr(x['kind'])}, {x['elements']}, {str(bool(x['change_while_powered'])).lower()}, {vbstr(x['storage'])})")
 elif op=='BIND_CONFIG_PIN': w(f"        runtime.BindConfigPin({vbstr(x['module'])}, {vbstr(x['pin'])}, {vbstr(x['role'])}, {vbstr(str(x.get('sampling') or ''))}, {j(x['source'])})")
 elif op=='DEFINE_PROPERTY':
  q={k:v for k,v in x.items() if k not in ('op','module','property','status')}; w(f"        runtime.DefineProperty({vbstr(x['module'])}, {vbstr(x['property'])}, {vbstr(x['status'])}, {j(q)})")
 elif op=='LINK': w(f"        runtime.Link({vbstr(x['id'])}, {vbstr(x['net'])}, {j(x['endpoints'])})")
 elif op=='CREATE_DEVICE_SLOT':
  q={k:v for k,v in x.items() if k not in ('op','slot_id','instance_id')}; w(f"        runtime.CreateDeviceSlot({vbstr(x['slot_id'])}, {vbstr(x['instance_id'])}, {j(q)})")
 elif op=='FINALIZE_BOARD': w(f"        runtime.FinalizeBoard({x['hardware_tits']}, {x['execution_tits']}, {x.get('default_execution_tits',x['execution_tits'])})")
 else: raise SystemExit('unsupported op '+op)
w('    End Sub'); w('End Class'); w('')
Path(a.out).write_text('\n'.join(L),encoding='utf-8'); print(json.dumps({'output':a.out,'board_id':board_id,'lines':len(L),'sha256':hashlib.sha256(Path(a.out).read_bytes()).hexdigest()},indent=2))
